import math

def check_integer(n):
    # Calculate the numerator: 3 * ((n+2)! + 1)
    try:
        factorial_term = math.factorial(n + 2)
    except ValueError:
        # Should not happen for non-negative integers n
        return False, "Error in factorial calculation"

    numerator = 3 * (factorial_term + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        # This only happens if n = 0.5, but we are checking integers.
        return False, "Zero denominator"

    if numerator % denominator == 0:
        return True, numerator // denominator
    else:
        return False, None

# Search for n from 0 up to 15
solutions = []
for n in range(16):
    is_int, value = check_integer(n)
    if is_int:
        solutions.append((n, value))

print("Found solutions (n, value):")
for n, value in solutions:
    print(f"n={n}, Value={value}")

print("\nAll solutions found up to n=15:", solutions)

