        # This case is impossible since 2n is even, 2n-1 is odd.
        return False

    numerator = 3 * (math.factorial(n+2) + 1)
    denominator = 2*n - 1

    if denominator == 0:
        return False # Should not happen

    return numerator % denominator == 0

test_values = [0, 1, 2, 3, 4, 5, 6]
results = {}
for n in test_values:
    results[n] = check(n)

print(results)

